struct WrongAck {
    action: u8,
}
impl NativeCipherConsumer for WrongAck {
    fn deliver<'a>(
        &'a self,
        delivery: &'a CipherDelivery,
    ) -> Verification<'a, DeliveryAcknowledgement> {
        Box::pin(async move {
            if self.action == 2 {
                return Err(Error::NativeDenied);
            }
            let mut receipt = delivery.acknowledge();
            if self.action == 0 {
                receipt.correlation[0] ^= 1;
